/* Navigation multi-pages (CSS) */
/* @view-transition { navigation: auto; } */

.trigger { anchor-name: --trigger; }

.tooltip {
  position: fixed;
  position-anchor: --trigger;
  position-area: top;
  position-try-fallbacks: flip-block;
}

/* Carte avec image : layout en 2 colonnes */
.card:has(> img) {
  grid-template-columns: 120px 1fr;
}

/* Formulaire invalide : bouton atténué */
form:has(:invalid) button[type="submit"] {
  opacity: .5;
}

.sidebar { container: card / inline-size; }

@container card (min-width: 400px) {
  .card { display: flex; gap: 1rem; }
}

@keyframes grow { from { scale: 0 1; } }

.progress-bar {
  transform-origin: left;
  animation: grow linear both;
  animation-timeline: scroll(root);
}

:root {
  --brand: oklch(65% 0.2 265);
  --brand-hover: oklch(from var(--brand) calc(l + 0.08) c h);
  --brand-muted: color-mix(in oklch, var(--brand) 30%, black);
}
